SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ==========================================================
-- 1. CREATION DES TABLES (SCHÉMA)
-- ==========================================================

CREATE TABLE IF NOT EXISTS `django_migrations` (`id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT, `app` varchar(255) NOT NULL, `name` varchar(255) NOT NULL, `applied` DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `django_content_type` (`id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT, `app_label` varchar(100) NOT NULL, `model` varchar(100) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `auth_group_permissions` (`id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT, `group_id` integer NOT NULL, `permission_id` integer NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `auth_permission` (`id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT, `content_type_id` integer NOT NULL, `codename` varchar(100) NOT NULL, `name` varchar(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `auth_group` (`id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT, `name` varchar(150) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_user_groups` (`id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT, `user_id` char(32) NOT NULL, `group_id` integer NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_user_user_permissions` (`id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT, `user_id` char(32) NOT NULL, `permission_id` integer NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `django_admin_log` (`id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT, `object_id` LONGTEXT NULL, `object_repr` varchar(200) NOT NULL, `action_flag` smallint unsigned NOT NULL CHECK (`action_flag` >= 0), `change_message` LONGTEXT NOT NULL, `content_type_id` integer NULL, `user_id` char(32) NOT NULL, `action_time` DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_conversation` (`id` char(32) NOT NULL PRIMARY KEY, `created_at` DATETIME(6) NOT NULL, `updated_at` DATETIME(6) NOT NULL, `participant_1_id` char(32) NOT NULL, `ride_id` char(32) NULL, `conversation_type` varchar(10) NOT NULL, `participant_2_id` char(32) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_notification` (`id` char(32) NOT NULL PRIMARY KEY, `title` varchar(255) NOT NULL, `message` LONGTEXT NOT NULL, `is_read` tinyint(1) NOT NULL, `created_at` DATETIME(6) NOT NULL, `user_id` char(32) NULL, `data` LONGTEXT NULL CHECK ((JSON_VALID(`data`) OR `data` IS NULL)), `type` varchar(50) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_message` (`id` char(32) NOT NULL PRIMARY KEY, `content` LONGTEXT NOT NULL, `is_read` tinyint(1) NOT NULL, `created_at` DATETIME(6) NOT NULL, `conversation_id` char(32) NOT NULL, `sender_id` char(32) NOT NULL, `attachment` varchar(100) NULL, `location_lat` double precision NULL, `location_lng` double precision NULL, `message_type` varchar(10) NOT NULL, `is_urgent` tinyint(1) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_appbranding` (`id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT, `logo` varchar(100) NULL, `logo_scale` double precision NOT NULL, `logo_position_x` double precision NOT NULL, `logo_position_y` double precision NOT NULL, `is_active` tinyint(1) NOT NULL, `updated_at` DATETIME(6) NOT NULL, `animation_type` varchar(50) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_verificationrequest` (`id` char(32) NOT NULL PRIMARY KEY, `selfie` varchar(100) NOT NULL, `id_front` varchar(100) NOT NULL, `id_back` varchar(100) NOT NULL, `status` varchar(20) NOT NULL, `created_at` DATETIME(6) NOT NULL, `updated_at` DATETIME(6) NOT NULL, `user_id` char(32) NOT NULL UNIQUE, `selfie_id` varchar(100) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_vehicle` (`id` char(32) NOT NULL PRIMARY KEY, `brand_model` varchar(255) NOT NULL, `color` varchar(50) NOT NULL, `license_plate` varchar(50) NOT NULL, `owner_id` char(32) NOT NULL, `driver_license_number` varchar(100) NULL, `license_expiration` DATE NULL, `vehicle_type` varchar(20) NOT NULL, `driver_license_photo` varchar(100) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_mobilesettings` (`id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT, `show_promotions` tinyint(1) NOT NULL, `updated_at` DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_promotion` (`id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT, `title` varchar(255) NOT NULL, `subtitle` varchar(255) NULL, `image` varchar(100) NOT NULL, `color` varchar(20) NOT NULL, `icon` varchar(50) NULL, `is_active` tinyint(1) NOT NULL, `position` integer unsigned NOT NULL CHECK (`position` >= 0), `created_at` DATETIME(6) NOT NULL, `updated_at` DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_userpreference` (`id` char(32) NOT NULL PRIMARY KEY, `music` tinyint(1) NOT NULL, `smoking` tinyint(1) NOT NULL, `chatty` tinyint(1) NOT NULL, `air_conditioner` tinyint(1) NOT NULL, `user_id` char(32) NOT NULL UNIQUE, `notes` LONGTEXT NULL, `luggage_allowed` tinyint(1) NOT NULL, `pets_allowed` tinyint(1) NOT NULL, `stops_allowed` tinyint(1) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_refundrequest` (`id` char(32) NOT NULL PRIMARY KEY, `amount` integer NOT NULL, `reason` LONGTEXT NOT NULL, `status` varchar(20) NOT NULL, `created_at` DATETIME(6) NOT NULL, `updated_at` DATETIME(6) NOT NULL, `booking_id` char(32) NOT NULL, `driver_id` char(32) NOT NULL, `passenger_id` char(32) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_rideseries` (`id` char(32) NOT NULL PRIMARY KEY, `start_date` DATE NOT NULL, `end_date` DATE NOT NULL, `repeat_type` varchar(20) NOT NULL, `week_days` LONGTEXT NULL CHECK ((JSON_VALID(`week_days`) OR `week_days` IS NULL)), `departure_time` time NOT NULL, `departure_location` varchar(255) NOT NULL, `arrival_location` varchar(255) NOT NULL, `price_per_seat` integer NOT NULL, `total_seats` integer NOT NULL, `created_at` DATETIME(6) NOT NULL, `driver_id` char(32) NOT NULL, `vehicle_id` char(32) NULL, `driver_payout` integer NOT NULL, `zemy_commission` integer NOT NULL, `accepts_parcels` tinyint(1) NOT NULL, `allowed_parcel_types` LONGTEXT NULL CHECK ((JSON_VALID(`allowed_parcel_types`) OR `allowed_parcel_types` IS NULL)), `max_dimensions` varchar(50) NULL, `max_parcels` integer NOT NULL, `max_weight_per_parcel` double precision NOT NULL, `price_per_parcel` integer NOT NULL, `arrival_latitude` double precision NULL, `arrival_longitude` double precision NULL, `departure_latitude` double precision NULL, `departure_longitude` double precision NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_parcel` (`id` char(32) NOT NULL PRIMARY KEY, `sender_name` varchar(255) NOT NULL, `sender_phone` varchar(20) NOT NULL, `receiver_name` varchar(255) NOT NULL, `receiver_phone` varchar(20) NOT NULL, `pickup_location` varchar(255) NOT NULL, `dropoff_location` varchar(255) NOT NULL, `description` LONGTEXT NOT NULL, `weight` double precision NOT NULL, `dimensions` varchar(50) NOT NULL, `estimated_value` integer NOT NULL, `photo` varchar(100) NULL, `special_instructions` LONGTEXT NULL, `price` integer NOT NULL, `zemy_commission` integer NOT NULL, `driver_payout` integer NOT NULL, `status` varchar(20) NOT NULL, `payment_status` varchar(20) NOT NULL, `qr_code_data` varchar(255) NULL UNIQUE, `created_at` DATETIME(6) NOT NULL, `updated_at` DATETIME(6) NOT NULL, `ride_id` char(32) NOT NULL, `sender_user_id` char(32) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_transaction` (`id` char(32) NOT NULL PRIMARY KEY, `driver_payout` integer NOT NULL, `total_price` integer NOT NULL, `status` varchar(20) NOT NULL, `created_at` DATETIME(6) NOT NULL, `updated_at` DATETIME(6) NOT NULL, `ride_id` char(32) NULL, `user_id` char(32) NOT NULL, `amount` integer NOT NULL, `parcel_id` char(32) NULL, `transaction_type` varchar(20) NOT NULL, `zemy_commission` integer NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_auditlog` (`id` char(32) NOT NULL PRIMARY KEY, `action` varchar(50) NOT NULL, `reason` LONGTEXT NULL, `ip_address` char(39) NULL, `created_at` DATETIME(6) NOT NULL, `admin_user_id` char(32) NULL, `target_user_id` char(32) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_moderationlog` (`id` char(32) NOT NULL PRIMARY KEY, `original_content` LONGTEXT NOT NULL, `modified_content` LONGTEXT NULL, `action_taken` varchar(20) NOT NULL, `detected_types` LONGTEXT NOT NULL CHECK ((JSON_VALID(`detected_types`) OR `detected_types` IS NULL)), `created_at` DATETIME(6) NOT NULL, `message_id` char(32) NULL, `sender_id` char(32) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_popularplace` (`id` char(32) NOT NULL PRIMARY KEY, `name` varchar(255) NOT NULL, `latitude` double precision NOT NULL, `longitude` double precision NOT NULL, `city` varchar(255) NULL, `created_at` DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_user` (`password` varchar(128) NOT NULL, `last_login` DATETIME(6) NULL, `is_superuser` tinyint(1) NOT NULL, `id` char(32) NOT NULL PRIMARY KEY, `full_name` varchar(255) NULL, `email` varchar(254) NULL UNIQUE, `phone` varchar(20) NOT NULL UNIQUE, `avatar` varchar(100) NULL, `rating` double precision NOT NULL, `is_verified` tinyint(1) NOT NULL, `created_at` DATETIME(6) NOT NULL, `is_active` tinyint(1) NOT NULL, `is_staff` tinyint(1) NOT NULL, `fcm_token` varchar(500) NULL, `parcel_rating` double precision NOT NULL, `parcels_completed` integer NOT NULL, `archive_reason` LONGTEXT NULL, `archived_at` DATETIME(6) NULL, `is_archived` tinyint(1) NOT NULL, `country` varchar(5) NOT NULL, `archived_by_id` char(32) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_passwordresetotp` (`id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT, `email` varchar(254) NOT NULL, `code` varchar(6) NOT NULL, `created_at` DATETIME(6) NOT NULL, `attempts` integer NOT NULL, `is_verified` tinyint(1) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_supportticket` (`id` char(32) NOT NULL PRIMARY KEY, `name` varchar(255) NOT NULL, `email` varchar(254) NOT NULL, `subject` varchar(255) NOT NULL, `category` varchar(50) NOT NULL, `message` LONGTEXT NOT NULL, `status` varchar(20) NOT NULL, `ticket_number` varchar(50) NULL UNIQUE, `ip_address` char(39) NULL, `created_at` DATETIME(6) NOT NULL, `updated_at` DATETIME(6) NOT NULL, `user_id` char(32) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_payment` (`id` char(32) NOT NULL PRIMARY KEY, `transaction_id` varchar(100) NOT NULL UNIQUE, `amount` integer NOT NULL, `status` varchar(20) NOT NULL, `created_at` DATETIME(6) NOT NULL, `updated_at` DATETIME(6) NOT NULL, `booking_id` char(32) NULL, `parcel_id` char(32) NULL, `user_id` char(32) NOT NULL, `last_verification_at` DATETIME(6) NULL, `verification_attempts` integer NOT NULL, `provider` varchar(50) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_financialsettings` (`id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT, `commission_percentage` double precision NOT NULL, `min_commission` integer NOT NULL, `max_commission` integer NULL, `is_commission_active` tinyint(1) NOT NULL, `updated_at` DATETIME(6) NOT NULL, `is_parcel_commission_active` tinyint(1) NOT NULL, `max_parcel_commission` integer NULL, `min_parcel_commission` integer NOT NULL, `parcel_commission_percentage` double precision NOT NULL, `price_margin_percent` integer NOT NULL, `price_per_km` integer NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_directionscache` (`id` char(32) NOT NULL PRIMARY KEY, `origin_place_id` varchar(150) NULL, `destination_place_id` varchar(150) NULL, `waypoints_hash` varchar(64) NOT NULL, `route_data` LONGTEXT NOT NULL CHECK ((JSON_VALID(`route_data`) OR `route_data` IS NULL)), `created_at` DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_rideleg` (`id` char(32) NOT NULL PRIMARY KEY, `start_location` varchar(255) NOT NULL, `end_location` varchar(255) NOT NULL, `start_latitude` double precision NOT NULL, `start_longitude` double precision NOT NULL, `end_latitude` double precision NOT NULL, `end_longitude` double precision NOT NULL, `departure_time` DATETIME(6) NOT NULL, `arrival_time` DATETIME(6) NOT NULL, `seats_available` integer NOT NULL, `price` integer NOT NULL, `order` integer NOT NULL, `ride_id` char(32) NOT NULL, `end_place_id` varchar(255) NULL, `start_place_id` varchar(255) NULL, `distance_m` integer NOT NULL, `duration_sec` integer NOT NULL, `leg_status` varchar(20) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_searchalert` (`id` char(32) NOT NULL PRIMARY KEY, `departure_location` varchar(255) NOT NULL, `arrival_location` varchar(255) NOT NULL, `departure_latitude` double precision NULL, `departure_longitude` double precision NULL, `arrival_latitude` double precision NULL, `arrival_longitude` double precision NULL, `desired_date` DATE NOT NULL, `seats_needed` integer NOT NULL, `is_active` tinyint(1) NOT NULL, `created_at` DATETIME(6) NOT NULL, `expires_at` DATETIME(6) NOT NULL, `passenger_id` char(32) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_ridewaypoint` (`id` char(32) NOT NULL PRIMARY KEY, `name` varchar(255) NOT NULL, `latitude` double precision NOT NULL, `longitude` double precision NOT NULL, `order` integer NOT NULL, `distance_from_start_m` integer NOT NULL, `leg_index` integer NOT NULL, `is_stopover` tinyint(1) NOT NULL, `ride_id` char(32) NOT NULL, `seats_available` integer NOT NULL, `duration_from_start_sec` integer NOT NULL, `waypoint_type` varchar(50) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_driverpayout` (`id` char(32) NOT NULL PRIMARY KEY, `amount` integer NOT NULL, `phone_number` varchar(30) NOT NULL, `status` varchar(20) NOT NULL, `admin_note` LONGTEXT NULL, `requested_at` DATETIME(6) NOT NULL, `paid_at` DATETIME(6) NULL, `driver_id` char(32) NOT NULL, `failed_at` DATETIME(6) NULL, `failure_code` varchar(50) NULL, `failure_reason` LONGTEXT NULL, `feexpay_reference` varchar(255) NULL, `operator` varchar(20) NOT NULL, `payment_mode` varchar(20) NOT NULL, `payout_reference` varchar(50) NULL UNIQUE, `processed_at` DATETIME(6) NULL, `ride_id` char(32) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_booking` (`id` char(32) NOT NULL PRIMARY KEY, `seats_booked` integer NOT NULL, `status` varchar(20) NOT NULL, `created_at` DATETIME(6) NOT NULL, `passenger_id` char(32) NOT NULL, `ride_id` char(32) NOT NULL, `payment_status` varchar(20) NOT NULL, `transaction_id` varchar(255) NULL, `arrival_location` varchar(255) NULL, `departure_location` varchar(255) NULL, `custom_price` integer NULL, `arrival_latitude` double precision NULL, `arrival_longitude` double precision NULL, `arrival_waypoint_order` integer NULL, `departure_latitude` double precision NULL, `departure_longitude` double precision NULL, `departure_waypoint_order` integer NULL, `driver_counter_price` integer NULL, `negotiation_message` LONGTEXT NULL, `passenger_proposed_price` integer NULL, `dropoff_location_extra` varchar(255) NULL, `dropoff_surcharge` integer NOT NULL, `pickup_location_extra` varchar(255) NULL, `pickup_surcharge` integer NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `api_ride` (`id` char(32) NOT NULL PRIMARY KEY, `departure_location` varchar(255) NOT NULL, `arrival_location` varchar(255) NOT NULL, `departure_date` DATE NOT NULL, `departure_time` time NOT NULL, `price_per_seat` integer NOT NULL, `total_seats` integer NOT NULL, `seats_available` integer NOT NULL, `status` varchar(20) NOT NULL, `created_at` DATETIME(6) NOT NULL, `driver_id` char(32) NOT NULL, `vehicle_id` char(32) NULL, `driver_latitude` double precision NULL, `driver_longitude` double precision NULL, `updated_at` DATETIME(6) NOT NULL, `series_id` char(32) NULL, `driver_payout` integer NOT NULL, `zemy_commission` integer NOT NULL, `accepts_parcels` tinyint(1) NOT NULL, `allowed_parcel_types` LONGTEXT NULL CHECK ((JSON_VALID(`allowed_parcel_types`) OR `allowed_parcel_types` IS NULL)), `max_dimensions` varchar(50) NULL, `max_parcels` integer NOT NULL, `max_weight_per_parcel` double precision NOT NULL, `parcels_available` integer NOT NULL, `price_per_parcel` integer NOT NULL, `description` LONGTEXT NULL, `arrival_latitude` double precision NULL, `arrival_longitude` double precision NULL, `departure_latitude` double precision NULL, `departure_longitude` double precision NULL, `air_conditioner` tinyint(1) NOT NULL, `chatty` tinyint(1) NOT NULL, `distance_km` double precision NULL, `duration_min` integer NULL, `luggage_allowed` tinyint(1) NOT NULL, `music` tinyint(1) NOT NULL, `pets_allowed` tinyint(1) NOT NULL, `smoking` tinyint(1) NOT NULL, `stops_allowed` tinyint(1) NOT NULL, `stopovers` LONGTEXT NULL CHECK ((JSON_VALID(`stopovers`) OR `stopovers` IS NULL)), `arrival_place_id` varchar(255) NULL, `departure_place_id` varchar(255) NULL, `auto_accept` tinyint(1) NOT NULL, `current_leg_index` integer NOT NULL, CONSTRAINT `ride_seats_available_non_negative` CHECK (`seats_available` >= 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `django_session` (`session_key` varchar(40) NOT NULL PRIMARY KEY, `session_data` LONGTEXT NOT NULL, `expire_date` DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `token_blacklist_blacklistedtoken` (`blacklisted_at` DATETIME(6) NOT NULL, `token_id` bigint NOT NULL UNIQUE, `id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `token_blacklist_outstandingtoken` (`token` LONGTEXT NOT NULL, `created_at` DATETIME(6) NULL, `expires_at` DATETIME(6) NOT NULL, `user_id` char(32) NULL, `jti` varchar(255) NOT NULL UNIQUE, `id` integer NOT NULL PRIMARY KEY AUTO_INCREMENT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


